@CrossOrigin
@RestController
@RequestMapping("/CandidateQuery")
public class CandidateQueryRestController extends BaseSpringRestController {
	
	public CandidateQueryRestController( CandidateService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Candidate using a UUID
     * @param		UUID candidateId
     * @return		Candidate
     */    
    @GetMapping("/load")
    public Candidate load( @RequestParam(required=true) UUID candidateId ) {
    	Candidate entity = null;

    	try {  
    		entity = service.getCandidate( new CandidateFetchOneSummary( candidateId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Candidate using Id " + candidateId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Candidate business objects
     * @return		Set<Candidate>
     */
    @GetMapping("/")
    public List<Candidate> loadAll() {                
    	List<Candidate> candidateList = null;
        
    	try {
            // load the Candidate
            candidateList = service.getAllCandidate();
            
            if ( candidateList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Candidates" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Candidates ", exc );
        	return null;
        }

        return candidateList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Candidate candidate = null;
    protected CandidateService service = null;
    private static final Logger LOGGER = Logger.getLogger(CandidateQueryRestController.class.getName());
    
}
